INSERT INTO course_revisions (id, course_id, status, title, summary, difficulty, estimated_minutes, lesson_count, submitted_at, published_at, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e003-0000-7000-8000-200000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-100000000001'), 'PUBLISHED', 'SQL 3: Gom nhóm', 'Biến dữ liệu chi tiết thành báo cáo: hàm tổng hợp COUNT, SUM, AVG, MIN, MAX và cách chúng xử lý NULL, GROUP BY một và nhiều cột, gom theo tháng, HAVING, đếm có điều kiện, gom nhóm sau JOIN và đếm số 0 bằng LEFT JOIN.', 'MEDIUM', 153, 13, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000')
INSERT INTO chapters (id, revision_id, title, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e003-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-200000000001'), 'Hàm tổng hợp', 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-200000000001'), 'GROUP BY', 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-200000000001'), 'HAVING', 3, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-200000000001'), 'Báo cáo với JOIN và GROUP BY', 4, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lessons (id, chapter_id, lesson_key, slug, title, body, position, estimated_minutes, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000001'), 'ham-tong-hop', 'COUNT, SUM, AVG, MIN, MAX', '## Từ nhiều dòng thành một con số\n\nHàm tổng hợp nhận **nhiều dòng** và trả **một giá trị**:\n\n- `COUNT(...)`: đếm.\n- `SUM(cột)`: tổng.\n- `AVG(cột)`: trung bình.\n- `MIN(cột)`, `MAX(cột)`: nhỏ nhất, lớn nhất.\n\n```sql\nSELECT COUNT(*) AS employee_count,\n       SUM(salary) AS total_salary,\n       MIN(salary) AS lowest_salary,\n       MAX(salary) AS highest_salary\nFROM employees;\n```\n\nKhông có GROUP BY, cả bảng được coi là **một nhóm** nên kết quả chỉ có một dòng.\n\n## Kết hợp với WHERE\n\nWHERE lọc dòng **trước** khi tính:\n\n```sql\nSELECT COUNT(*) AS delivered_orders\nFROM orders\nWHERE status = ''DELIVERED'';\n```\n\nKết quả: 21 đơn đã giao.\n\n## Tổng hợp trên biểu thức\n\n```sql\nSELECT SUM(quantity * unit_price) AS gross_revenue\nFROM order_items;\n```\n\n## MIN, MAX với chữ và ngày\n\nMIN, MAX dùng được cho cả ngày và chuỗi: `MIN(order_date)` là đơn đầu tiên, `MAX(name)` là tên đứng cuối theo bảng chữ cái.\n\n## Thử ngay\n\nÔ dưới tìm ngày của đơn đầu tiên và đơn cuối cùng. Thử thêm COUNT(*) để biết có bao nhiêu đơn.', 1, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000002'), 'count-va-null', 'COUNT(*), COUNT(cột) và COUNT(DISTINCT)', '## Ba cách đếm, ba ý nghĩa\n\n```sql\nSELECT COUNT(*) AS all_rows,\n       COUNT(city) AS with_city,\n       COUNT(DISTINCT city) AS distinct_cities\nFROM customers;\n```\n\nKết quả: 15, 13 và 6.\n\n- `COUNT(*)` đếm **mọi dòng**.\n- `COUNT(cột)` chỉ đếm dòng mà cột đó **khác NULL**. Hai khách chưa khai thành phố không được tính.\n- `COUNT(DISTINCT cột)` đếm số **giá trị khác nhau**, cũng bỏ NULL.\n\n## Chọn cách đếm theo câu hỏi\n\n- "Có bao nhiêu nhân viên?": `COUNT(*)`, ra 13.\n- "Bao nhiêu người đã có lương?": `COUNT(salary)`, ra 12.\n- "Có bao nhiêu phòng ban?": `COUNT(DISTINCT department)`, ra 4.\n\n## COUNT(DISTINCT) chữa bệnh nhân dòng\n\nỞ chặng Nối bảng, nối đơn với dòng hàng làm một đơn xuất hiện nhiều lần. Đếm số đơn có mua phụ kiện (danh mục 6):\n\n```sql\nSELECT COUNT(*) AS item_rows, COUNT(DISTINCT oi.order_id) AS orders\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id\nWHERE p.category_id = 6;\n```\n\n`COUNT(*)` đếm dòng hàng, còn `COUNT(DISTINCT oi.order_id)` mới là số đơn.\n\n## Thử ngay\n\nÔ dưới so sánh ba cách đếm trên bảng nhân viên.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000003'), 'avg-va-lam-tron', 'AVG, NULL và làm tròn', '## AVG bỏ qua NULL\n\n`AVG(salary)` chia tổng lương cho **số người có lương**, không phải cho số nhân viên:\n\n```sql\nSELECT AVG(salary) AS avg_of_known,\n       SUM(salary) / COUNT(*) AS avg_over_everyone\nFROM employees;\n```\n\nKết quả khác nhau: khoảng 25.583.333 so với 23.615.385, vì Ông Tín chưa có lương. Câu nào đúng tuỳ câu hỏi nghiệp vụ. Muốn coi lương trống là 0, viết `AVG(COALESCE(salary, 0))`.\n\nSUM, MIN, MAX cũng bỏ qua NULL. Nếu **mọi** giá trị đều NULL, các hàm này trả NULL, riêng COUNT trả 0.\n\n## Làm tròn\n\n`ROUND(x, n)` làm tròn tới n chữ số thập phân:\n\n```sql\nSELECT ROUND(AVG(salary)) AS avg_salary\nFROM employees;\n```\n\n```sql\nSELECT ROUND(AVG(price), 2) AS avg_price\nFROM products;\n```\n\n## Trung bình của số nguyên\n\n`AVG` trên cột số nguyên vẫn trả số thập phân trên PostgreSQL. Nhưng tự tính `SUM(quantity) / COUNT(*)` thì là chia số nguyên, phần lẻ bị bỏ. Nhân thêm `1.0` để tránh: `SUM(quantity) * 1.0 / COUNT(*)`.\n\n## Thử ngay\n\nÔ dưới tính số lượng trung bình mỗi dòng hàng theo hai cách. Thử bỏ `* 1.0`.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000004'), 'group-by-co-ban', 'Gom nhóm với GROUP BY', '## Một con số cho mỗi nhóm\n\n`GROUP BY` chia các dòng thành nhóm có cùng giá trị, rồi hàm tổng hợp tính **riêng cho từng nhóm**:\n\n```sql\nSELECT status, COUNT(*) AS orders\nFROM orders\nGROUP BY status\nORDER BY orders DESC;\n```\n\nKết quả: DELIVERED 21, PENDING 4, CANCELLED 3, SHIPPING 2. Mỗi nhóm cho ra đúng một dòng.\n\n## Hình dung\n\n1. Database đọc 30 đơn.\n2. Xếp chúng vào 4 "giỏ" theo status.\n3. Đếm số đơn trong mỗi giỏ.\n\n## Nhiều hàm tổng hợp cùng lúc\n\n```sql\nSELECT department,\n       COUNT(*) AS headcount,\n       ROUND(AVG(salary)) AS avg_salary,\n       MAX(salary) AS max_salary\nFROM employees\nGROUP BY department;\n```\n\n## NULL là một nhóm\n\nCác dòng có giá trị NULL ở cột gom nhóm được xếp chung vào **một nhóm NULL**. Thử `GROUP BY city` trên bảng khách để thấy.\n\n## Thử ngay\n\nÔ dưới đếm khách theo thành phố. Thử sắp theo số khách giảm dần.', 1, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000005'), 'quy-tac-cot-trong-select', 'Quy tắc cột trong SELECT khi có GROUP BY', '## Lỗi kinh điển\n\n```sql\n-- lỗi: name phải nằm trong GROUP BY hoặc hàm tổng hợp\nSELECT department, name, COUNT(*)\nFROM employees\nGROUP BY department;\n```\n\nPostgreSQL báo: *column "employees.name" must appear in the GROUP BY clause or be used in an aggregate function*.\n\n## Vì sao\n\nMỗi nhóm thành **một dòng**. Phòng Kinh doanh có 5 người, vậy cột `name` của dòng đó là tên ai? Database không đoán.\n\n## Quy tắc\n\nMỗi cột trong SELECT phải:\n\n1. Nằm trong `GROUP BY`, hoặc\n2. Nằm trong một hàm tổng hợp.\n\nCách sửa tuỳ ý định:\n\n```sql\nSELECT department, MIN(name) AS first_name_alphabetically, COUNT(*)\nFROM employees\nGROUP BY department;\n```\n\n```sql\nSELECT department, STRING_AGG(name, '', '' ORDER BY name) AS members\nFROM employees\nGROUP BY department;\n```\n\n`STRING_AGG` nối giá trị của cả nhóm thành một chuỗi, rất tiện để xem nhanh thành viên của nhóm.\n\n## Ngoại lệ hợp lệ\n\nGom theo khoá chính thì được chọn các cột khác của bảng đó, vì mỗi khoá chính chỉ ứng với một dòng: `GROUP BY c.id` rồi `SELECT c.name` vẫn chạy trên PostgreSQL.\n\n## Thử ngay\n\nÔ dưới liệt kê thành viên từng phòng ban.', 2, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000006'), 'group-by-nhieu-cot', 'Gom nhóm theo nhiều cột', '## Nhóm là tổ hợp giá trị\n\n`GROUP BY a, b` tạo một nhóm cho **mỗi tổ hợp** (a, b) xuất hiện trong dữ liệu:\n\n```sql\nSELECT c.city, o.status, COUNT(*) AS orders\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nGROUP BY c.city, o.status\nORDER BY c.city, o.status;\n```\n\nTổ hợp không có dòng nào thì **không xuất hiện**. Ví dụ Cần Thơ không có đơn huỷ nên không có dòng "Cần Thơ, CANCELLED". Muốn có dòng số 0, cần CROSS JOIN tạo khung rồi LEFT JOIN như ở chặng trước.\n\n## Thứ tự cột trong GROUP BY\n\nThứ tự cột trong GROUP BY không đổi kết quả, chỉ thứ tự trong ORDER BY mới quyết định cách sắp xếp.\n\n## Thử ngay\n\nÔ dưới đếm nhân viên theo phòng ban và năm vào làm.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000007'), 'gom-theo-bieu-thuc', 'Gom theo tháng và theo phân khúc', '## Gom theo tháng\n\nBáo cáo theo thời gian hiếm khi gom theo từng ngày. Dùng `DATE_TRUNC` để đưa mọi ngày về đầu tháng rồi gom:\n\n```sql\nSELECT DATE_TRUNC(''month'', order_date)::date AS month, COUNT(*) AS orders\nFROM orders\nGROUP BY DATE_TRUNC(''month'', order_date)\nORDER BY month;\n```\n\n## Doanh thu theo tháng\n\n```sql\nSELECT DATE_TRUNC(''month'', o.order_date)::date AS month,\n       SUM(oi.quantity * oi.unit_price) AS revenue\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id\nWHERE o.status = ''DELIVERED''\nGROUP BY 1\nORDER BY 1;\n```\n\n`GROUP BY 1` nghĩa là gom theo cột thứ nhất của SELECT. Viết tắt tiện lợi khi biểu thức dài, nhưng dễ sai nếu bạn đổi thứ tự cột, nên dùng có chừng mực.\n\n## Gom theo phân khúc tự định nghĩa\n\nBiểu thức CASE cũng gom được:\n\n```sql\nSELECT CASE\n           WHEN price >= 20000000 THEN ''Cao cấp''\n           WHEN price >= 1000000 THEN ''Tầm trung''\n           ELSE ''Phổ thông''\n       END AS segment,\n       COUNT(*) AS products\nFROM products\nGROUP BY 1;\n```\n\n## Thử ngay\n\nÔ dưới tính doanh thu đã giao theo từng quý. Thử đổi sang theo tháng.', 4, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000008'), 'loc-nhom-voi-having', 'Lọc nhóm với HAVING', '## Lọc sau khi đã tính\n\nMuốn tìm khách đặt từ 3 đơn trở lên, bạn không thể viết `WHERE COUNT(*) >= 3`: WHERE chạy trước khi đếm. `HAVING` lọc **nhóm**, sau khi hàm tổng hợp đã tính xong:\n\n```sql\nSELECT customer_id, COUNT(*) AS orders\nFROM orders\nGROUP BY customer_id\nHAVING COUNT(*) >= 3\nORDER BY orders DESC;\n```\n\nKết quả: khách 1 có 5 đơn, khách 2 có 4 đơn, khách 4 và 6 mỗi người 3 đơn.\n\n## Thứ tự thực thi đầy đủ\n\n1. `FROM`, `JOIN`\n2. `WHERE`: lọc dòng.\n3. `GROUP BY`: gom nhóm.\n4. `HAVING`: lọc nhóm.\n5. `SELECT`\n6. `ORDER BY`\n7. `LIMIT`\n\n## HAVING với điều kiện khác\n\n```sql\nSELECT department, ROUND(AVG(salary)) AS avg_salary\nFROM employees\nGROUP BY department\nHAVING AVG(salary) > 20000000;\n```\n\nTrên PostgreSQL, HAVING không dùng được bí danh của SELECT, hãy lặp lại biểu thức như trên.\n\n## Thử ngay\n\nÔ dưới tìm sản phẩm đã bán được tổng số lượng từ 3 trở lên.', 1, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000009'), 'where-hay-having', 'WHERE hay HAVING', '## Câu hỏi để chọn\n\n> Điều kiện này nói về **từng dòng** hay về **cả nhóm**?\n\n- Về từng dòng (trạng thái đơn, thành phố của khách): **WHERE**.\n- Về kết quả tổng hợp (tổng tiền, số đơn): **HAVING**.\n\n## Dùng cả hai\n\n> Những khách có tổng giá trị đơn **đã giao** trên 20 triệu.\n\n```sql\nSELECT o.customer_id, SUM(oi.quantity * oi.unit_price) AS delivered_value\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id\nWHERE o.status = ''DELIVERED''\nGROUP BY o.customer_id\nHAVING SUM(oi.quantity * oi.unit_price) > 20000000\nORDER BY delivered_value DESC;\n```\n\n`status = ''DELIVERED''` nói về từng đơn nên nằm ở WHERE. Tổng tiền nói về cả nhóm nên nằm ở HAVING.\n\n## Đặt nhầm chỗ\n\nĐưa điều kiện của dòng vào HAVING đôi khi vẫn chạy nếu cột đó có trong GROUP BY, nhưng database phải gom **mọi** dòng rồi mới bỏ bớt, chậm hơn và khó đọc. Lọc được sớm thì lọc ở WHERE.\n\n## Thử ngay\n\nÔ dưới tìm thành phố có từ 3 khách trở lên, chỉ tính khách đăng ký trong năm 2025.', 2, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000010'), 'doanh-thu-theo-nhom', 'Doanh thu theo danh mục và theo khách', '## Doanh thu theo danh mục\n\nNối dòng hàng tới sản phẩm và danh mục, rồi gom:\n\n```sql\nSELECT cat.name AS category,\n       SUM(oi.quantity) AS units,\n       SUM(oi.quantity * oi.unit_price) AS revenue\nFROM order_items oi\nJOIN orders o ON o.id = oi.order_id\nJOIN products p ON p.id = oi.product_id\nJOIN categories cat ON cat.id = p.category_id\nWHERE o.status = ''DELIVERED''\nGROUP BY cat.name\nORDER BY revenue DESC;\n```\n\n## Top khách hàng\n\n```sql\nSELECT c.name,\n       COUNT(DISTINCT o.id) AS orders,\n       SUM(oi.quantity * oi.unit_price) AS revenue\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items oi ON oi.order_id = o.id\nWHERE o.status = ''DELIVERED''\nGROUP BY c.id, c.name\nORDER BY revenue DESC\nLIMIT 3;\n```\n\nTrần Bình dẫn đầu với hơn 65 triệu. Để ý `COUNT(DISTINCT o.id)`: sau khi nối tới dòng hàng, `COUNT(*)` sẽ đếm dòng hàng chứ không phải đơn.\n\n## Gom theo id hay theo tên\n\nGom theo `c.name` sẽ gộp nhầm hai khách trùng tên. Gom theo `c.id, c.name` an toàn hơn: id đảm bảo mỗi khách một nhóm, name để hiển thị.\n\n## Thử ngay\n\nÔ dưới tính giá trị trung bình mỗi đơn đã giao. Gợi ý: tính tổng theo đơn trước sẽ học ở chặng Truy vấn lồng; ở đây chia tổng tiền cho số đơn khác nhau.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000011'), 'dem-co-dieu-kien', 'Đếm và cộng có điều kiện', '## Nhiều con số trên cùng một dòng\n\nBáo cáo thường cần nhiều chỉ số theo điều kiện khác nhau trên cùng một dòng, ví dụ mỗi khách: tổng số đơn, số đơn đã giao, số đơn huỷ.\n\n## SUM(CASE ...)\n\n```sql\nSELECT customer_id,\n       COUNT(*) AS orders,\n       SUM(CASE WHEN status = ''DELIVERED'' THEN 1 ELSE 0 END) AS delivered,\n       SUM(CASE WHEN status = ''CANCELLED'' THEN 1 ELSE 0 END) AS cancelled\nFROM orders\nGROUP BY customer_id\nORDER BY customer_id;\n```\n\nCASE biến mỗi dòng thành 1 hoặc 0, SUM cộng lại thành số dòng thoả điều kiện. Kỹ thuật này chạy trên mọi database.\n\n## FILTER trên PostgreSQL\n\nPostgreSQL có cú pháp gọn hơn:\n\n```sql\nSELECT customer_id,\n       COUNT(*) AS orders,\n       COUNT(*) FILTER (WHERE status = ''DELIVERED'') AS delivered,\n       COUNT(*) FILTER (WHERE status = ''CANCELLED'') AS cancelled\nFROM orders\nGROUP BY customer_id\nORDER BY customer_id;\n```\n\n## Tỉ lệ\n\nTỉ lệ đơn huỷ toàn cửa hàng, tính bằng phần trăm:\n\n```sql\nSELECT ROUND(100.0 * COUNT(*) FILTER (WHERE status = ''CANCELLED'') / COUNT(*), 1) AS cancel_rate\nFROM orders;\n```\n\nNhớ `100.0` để tránh chia số nguyên.\n\n## Thử ngay\n\nÔ dưới tính, cho mỗi phòng ban, số người lương từ 20 triệu và số người dưới 20 triệu.', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000012'), 'dem-so-0-voi-left-join', 'Đếm cả số 0 với LEFT JOIN', '## Khách chưa có đơn đi đâu mất\n\n```sql\nSELECT c.name, COUNT(*) AS orders\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nGROUP BY c.id, c.name;\n```\n\nChỉ có 12 khách. Ba khách chưa mua biến mất vì INNER JOIN.\n\n## LEFT JOIN và COUNT(cột)\n\n```sql\nSELECT c.name, COUNT(o.id) AS orders\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nGROUP BY c.id, c.name\nORDER BY orders, c.name;\n```\n\nHai chi tiết quyết định:\n\n- **LEFT JOIN** để giữ khách chưa có đơn.\n- **COUNT(o.id)** chứ không phải `COUNT(*)`. Với khách chưa có đơn, LEFT JOIN vẫn tạo **một dòng** với `o.id` là NULL. `COUNT(*)` đếm dòng đó thành 1, còn `COUNT(o.id)` bỏ NULL nên ra 0.\n\n## Tổng tiền bằng 0 thay vì NULL\n\nSUM trên nhóm toàn NULL trả NULL. Bọc COALESCE để hiển thị 0:\n\n```sql\nSELECT p.name, COALESCE(SUM(oi.quantity), 0) AS units_sold\nFROM products p\nLEFT JOIN order_items oi ON oi.product_id = p.id\nGROUP BY p.id, p.name\nORDER BY units_sold, p.name;\n```\n\n## Thử ngay\n\nÔ dưới đếm số người mỗi quản lý phụ trách trực tiếp, kể cả người không quản lý ai.', 3, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-400000000013'), UUID_TO_BIN('01a1e003-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-500000000013'), 'on-tap-gom-nhom', 'Ôn tập: viết báo cáo hoàn chỉnh', '## Khung tư duy cho mọi báo cáo\n\n1. **Mỗi dòng kết quả là gì?** Một khách, một tháng, một danh mục... Đó là GROUP BY.\n2. **Cần những chỉ số nào?** COUNT, SUM, AVG, đếm có điều kiện.\n3. **Dữ liệu đi qua những bảng nào?** JOIN, và có cần LEFT JOIN để giữ nhóm trống không.\n4. **Lọc dòng gì trước khi tính?** WHERE.\n5. **Lọc nhóm gì sau khi tính?** HAVING.\n6. **Sắp và cắt thế nào?** ORDER BY, LIMIT.\n\n## Ví dụ: báo cáo theo thành phố\n\n> Mỗi thành phố: số khách, số khách đã từng mua, tổng giá trị đơn đã giao. Thành phố trống ghi "Chưa cập nhật".\n\n```sql\nSELECT COALESCE(c.city, ''Chưa cập nhật'') AS city,\n       COUNT(DISTINCT c.id) AS customers,\n       COUNT(DISTINCT o.customer_id) AS buyers,\n       COALESCE(SUM(oi.quantity * oi.unit_price) FILTER (WHERE o.status = ''DELIVERED''), 0) AS delivered_value\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nLEFT JOIN order_items oi ON oi.order_id = o.id\nGROUP BY COALESCE(c.city, ''Chưa cập nhật'')\nORDER BY delivered_value DESC;\n```\n\n## Tự luyện\n\n1. Số sản phẩm và giá trung bình của từng danh mục, kể cả danh mục chưa có sản phẩm.\n2. Những tháng có từ 3 đơn trở lên.\n3. Phòng ban có quỹ lương lớn nhất.\n\nChặng tiếp theo, **SQL 4: Truy vấn lồng**, giúp bạn trả lời những câu hỏi mà một lần GROUP BY không đủ, như "nhân viên lương cao hơn trung bình phòng mình".', 4, 15, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lesson_cells (id, lesson_id, cell_key, position, starter_sql, dialect, dataset_version_id, dataset_variant_id, dataset_checksum, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000001'), 1, 'SELECT MIN(order_date) AS first_order, MAX(order_date) AS last_order\nFROM orders;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000002'), 2, 'SELECT COUNT(*) AS employee_count, SUM(salary) AS total_salary,\n       MIN(salary) AS lowest_salary, MAX(salary) AS highest_salary\nFROM employees;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000003'), 1, 'SELECT COUNT(*) AS employees,\n       COUNT(salary) AS with_salary,\n       COUNT(DISTINCT department) AS departments\nFROM employees;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000004'), 2, 'SELECT COUNT(*) AS item_rows, COUNT(DISTINCT oi.order_id) AS orders\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id\nWHERE p.category_id = 6;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000005'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000005'), 1, 'SELECT AVG(quantity) AS avg_quantity,\n       SUM(quantity) * 1.0 / COUNT(*) AS manual_avg,\n       SUM(quantity) / COUNT(*) AS integer_division\nFROM order_items;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000006'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000006'), 2, 'SELECT ROUND(AVG(salary)) AS avg_of_known,\n       ROUND(AVG(COALESCE(salary, 0))) AS avg_counting_null_as_zero\nFROM employees;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000007'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000007'), 1, 'SELECT city, COUNT(*) AS customers\nFROM customers\nGROUP BY city\nORDER BY customers DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000008'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000008'), 2, 'SELECT department, COUNT(*) AS headcount, ROUND(AVG(salary)) AS avg_salary\nFROM employees\nGROUP BY department;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000009'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000009'), 1, 'SELECT department, COUNT(*) AS headcount,\n       STRING_AGG(name, '', '' ORDER BY name) AS members\nFROM employees\nGROUP BY department;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000010'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000010'), 1, 'SELECT department, EXTRACT(YEAR FROM hire_date) AS hire_year, COUNT(*) AS headcount\nFROM employees\nGROUP BY department, EXTRACT(YEAR FROM hire_date)\nORDER BY department, hire_year;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000011'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000011'), 1, 'SELECT EXTRACT(QUARTER FROM o.order_date) AS quarter,\n       SUM(oi.quantity * oi.unit_price) AS revenue\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id\nWHERE o.status = ''DELIVERED''\nGROUP BY 1\nORDER BY 1;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000012'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000012'), 1, 'SELECT p.name, SUM(oi.quantity) AS units_sold\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id\nGROUP BY p.name\nHAVING SUM(oi.quantity) >= 3\nORDER BY units_sold DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000013'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000013'), 1, 'SELECT city, COUNT(*) AS customers\nFROM customers\nWHERE signup_date BETWEEN ''2025-01-01'' AND ''2025-12-31''\nGROUP BY city\nHAVING COUNT(*) >= 3;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000014'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000014'), 1, 'SELECT SUM(oi.quantity * oi.unit_price) / COUNT(DISTINCT o.id) AS avg_order_value\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id\nWHERE o.status = ''DELIVERED'';', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000015'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000015'), 2, 'SELECT cat.name AS category, SUM(oi.quantity * oi.unit_price) AS revenue\nFROM order_items oi\nJOIN orders o ON o.id = oi.order_id\nJOIN products p ON p.id = oi.product_id\nJOIN categories cat ON cat.id = p.category_id\nWHERE o.status = ''DELIVERED''\nGROUP BY cat.name\nORDER BY revenue DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000016'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000016'), 1, 'SELECT department,\n       COUNT(*) FILTER (WHERE salary >= 20000000) AS from_20m,\n       COUNT(*) FILTER (WHERE salary < 20000000) AS under_20m\nFROM employees\nGROUP BY department;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000017'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000017'), 1, 'SELECT m.name AS manager, COUNT(e.id) AS direct_reports\nFROM employees m\nLEFT JOIN employees e ON e.manager_id = m.id\nGROUP BY m.id, m.name\nORDER BY direct_reports DESC, m.name;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e003-0000-7000-8000-600000000018'), UUID_TO_BIN('01a1e003-0000-7000-8000-400000000013'), UUID_TO_BIN('01a1e003-0000-7000-8000-700000000018'), 1, 'SELECT cat.name AS category, COUNT(p.id) AS products, ROUND(AVG(p.price)) AS avg_price\nFROM categories cat\nLEFT JOIN products p ON p.category_id = cat.id\nGROUP BY cat.id, cat.name\nORDER BY products DESC, cat.name;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
